"contenttype":"jsjQuery","contents":"$(document).on('click', function(event) {
 // Avoid triggering when the button itself or its children are clicked
 if (!$(event.target).closest('.hideMasterMenuButton').length) {
 event.stopPropagation();
 $(".hideMasterMenuButton").trigger("click");
 }
});
